/** Resolve only a measured club asset; unknown or malformed input has no borrowed contour. */
export function resolvePlayerCardArtPerimeterPath(assetUrl: string | null | undefined): string | null {
  if (!assetUrl) return null;
  let path: string;
  try { path = decodeURIComponent(assetUrl.split(/[?#]/, 1)[0]); } catch { return null; }
  const canonical = path.replace(/\.(?:png|webp)$/i, "")
    .replace(/^\/touchlineArena\/cards\/templates\/(?:zoom|live-compact|compact)\/clubs\//, "/touchlineArena/cards/templates/clubs/");
  return Object.hasOwn(CARD_ART_PERIMETER_PATHS.player, canonical)
    ? CARD_ART_PERIMETER_PATHS.player[canonical as keyof typeof CARD_ART_PERIMETER_PATHS.player] : null;
}
